beforeExample:
import org.eclipse.swt.graphics.RGB;
import org.eclipse.swt.widgets.Display;
import org.eclipse.swt.SWT;

public class TestClass {
    public void cacheColors(Display display) {
        RGB BG_COLOR_RGB= display.getSystemColor(SWT.COLOR_INFO_BACKGROUND).getRGB();
        RGB FG_COLOR_RGB= display.getSystemColor(SWT.COLOR_INFO_FOREGROUND).getRGB();
    }
}

afterExample:
import org.eclipse.swt.graphics.RGB;
import org.eclipse.swt.widgets.Display;
import org.eclipse.jface.resource.JFaceColors;

public class TestClass {
    public void cacheColors(Display display) {
        RGB BG_COLOR_RGB= JFaceColors.getInformationViewerBackgroundColor(display).getRGB();
        RGB FG_COLOR_RGB= JFaceColors.getInformationViewerForegroundColor(display).getRGB();
    }
}

